(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.035-t*0.5)*8 + Math.cos(y*0.028+t*0.45)*6;
  const w2y = Math.cos(y*0.032+t*0.55)*8 + Math.sin(x*0.025-t*0.4)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.6+1)*50, 0.11, 2.1],
    [400+Math.cos(t*0.45+2)*60, 200+Math.sin(t*0.8+4)*55, 0.085, 2.4],
    [200+Math.sin(t*0.55+6)*90, 220+Math.cos(t*0.75)*65, 0.075, 1.8]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    const wave2 = Math.sin(d*f*1.618 - t*sp*0.78);
    aS += wave;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    hS += wave * wave2 * 0.5;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, harm = hS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = Math.sin(dist*0.07-ang*5+t*0.8)*Math.cos(dist*0.03+ang*2-t*1.8)*0.25;
  const fiber = Math.sin(ang*8+dist*0.06-t*2)*Math.sin(ang*3-dist*0.04+t*1.2)*0.2;
  const pulse = Math.sin(dist*0.08-t*3)*Math.exp(-dist*0.005)*0.3;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + spiral2 + fiber + pulse + harm*0.4)*2.0);
  const laplacian = Math.sin(sx*0.2)*Math.sin(sy*0.2) + Math.sin((sx-sy)*0.15+t*0.5)*0.4 + Math.sin((sx+sy)*0.18-t*0.7)*0.3;
  const cell = Math.tanh((laplacian + Math.sin(sx*0.15)*Math.sin(sy*0.15))*1.2)*0.3;
  const edge = reaction - Math.tanh((act*0.5 - inh*0.5 + bg*0.2 + spiral*0.5)*1.8);
  const edgeDetect = 1.0 + Math.abs(edge)*2.5*Math.exp(-Math.abs(edge)*4);
  const blend = reaction*0.65 + cell*0.2 + harm*0.15;
  const v = blend*0.5+0.5;
  const pal = [[6,12,52],[10,45,88],[12,85,115],[18,140,130],[45,170,120],[180,185,70],[220,155,55],[210,100,60],[175,55,70],[120,30,65],[55,18,55],[12,10,42],[6,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.25;
  const highlight = Math.max(0, reaction-0.5)*2;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edgeDetect + highlight*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edgeDetect + highlight*25)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edgeDetect + highlight*15)|0)
  ];
}
